    path: PathBuf,
    size: u64,
    blocks: Option<u64>,
    tag: Span,
    readonly: bool,
    modified: Option<SystemTime>,
    is_symlink: bool,
    is_dir: bool,
    is_file: bool,
}

impl FileInfo {
    pub fn new(path: impl Into<PathBuf>, deref: bool, tag: Span) -> Result<Self, ShellError> {
        let path = path.into();
        let m = if deref {
            std::fs::metadata(&path)
        } else {
            std::fs::symlink_metadata(&path)
        };

        match m {
            Ok(d) => {
                let block_size = file_real_size_fast(&path, &d).ok();

                Ok(FileInfo {
                    path,
                    blocks: block_size,
                    size: d.len(),
                    tag,
                    readonly: d.permissions().readonly(),
                    modified: d.modified().ok(),
                    is_symlink: d.file_type().is_symlink(),
                    is_dir: d.is_dir(),
                    is_file: d.is_file(),
                })
            }
            Err(e) => Err(e.into()),
        }
    }

    pub fn from_ls_metadata(
        path: impl Into<PathBuf>,
        metadata: Option<&std::fs::Metadata>,
        tag: Span,
